"""Catalan numbers: formula, DP, and balanced-parentheses enumeration.

Usage: python catalan.py [n]   (default 5)
"""
import sys
from math import comb


def catalan(n):
    return comb(2 * n, n) // (n + 1)


def parens(n):
    """All balanced strings of n pairs, generated by backtracking."""
    out = []

    def go(s, o, c):
        if len(s) == 2 * n:
            out.append(s)
            return
        if o < n:
            go(s + "(", o + 1, c)
        if c < o:
            go(s + ")", o, c + 1)

    go("", 0, 0)
    return out


if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 5
    print("C(0..%d) =" % n, [catalan(i) for i in range(n + 1)])
    if n <= 5:
        print(*parens(n), sep="\n")
    assert len(parens(min(n, 8))) == catalan(min(n, 8))
